text:
#categories {
  & > .category {
    margin-inline: 6px;
    border-color: transparent !important;

    &[selected] {
      font-weight: 500;
    }
  }

  @media not (forced-colors) {
    & > .category[selected] {
      background-color: var(--button-background-color) !important;
      color: unset;
    }
  }
}
